solution.solution.cpp:
#include <algorithm>
#include <climits>
#include <memory>
#include <vector>

class AvlSet
{
public:
    bool insert(int key)
    {
        bool added = insert(root_, key);
        if (added) ++size_;
        return added;
    }

    bool erase(int key)
    {
        bool removed = erase(root_, key);
        if (removed) --size_;
        return removed;
    }

    bool contains(int key) const
    {
        const Node* n = root_.get();
        while (n && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
        return n != nullptr;
    }

    std::size_t size() const { return size_; }
    int height() const { return heightOf(root_); }

    std::vector<int> toVector() const
    {
        std::vector<int> out;
        collect(root_.get(), out);
        return out;
    }

    bool isValid() const
    {
        int h;
        long long lo = LLONG_MIN, hi = LLONG_MAX;
        return check(root_.get(), lo, hi, h);
    }

private:
    struct Node
    {
        int key;
        int height = 0;
        std::unique_ptr<Node> left, right;
    };

    static int heightOf(const std::unique_ptr<Node>& n) { return n ? n->height : -1; }
    static void update(Node& n) { n.height = 1 + std::max(heightOf(n.left), heightOf(n.right)); }
    static int balance(const Node& n) { return heightOf(n.left) - heightOf(n.right); }

    static void rotateRight(std::unique_ptr<Node>& link)
    {
        std::unique_ptr<Node> x = std::move(link->left);
        link->left = std::move(x->right);
        update(*link);
        x->right = std::move(link);
        update(*x);
        link = std::move(x);
    }

    static void rotateLeft(std::unique_ptr<Node>& link)
    {
        std::unique_ptr<Node> x = std::move(link->right);
        link->right = std::move(x->left);
        update(*link);
        x->left = std::move(link);
        update(*x);
        link = std::move(x);
    }

    static void rebalance(std::unique_ptr<Node>& link)
    {
        update(*link);
        int b = balance(*link);
        if (b > 1)
        {
            if (balance(*link->left) < 0) rotateLeft(link->left);
            rotateRight(link);
        }
        else if (b < -1)
        {
            if (balance(*link->right) > 0) rotateRight(link->right);
            rotateLeft(link);
        }
    }

    static bool insert(std::unique_ptr<Node>& link, int key)
    {
        if (!link)
        {
            link = std::make_unique<Node>();
            link->key = key;
            return true;
        }
        if (key == link->key) return false;
        bool added = insert(key < link->key ? link->left : link->right, key);
        if (added) rebalance(link);
        return added;
    }

    static int takeMin(std::unique_ptr<Node>& link)       // removes and returns the smallest key below link
    {
        if (!link->left)
        {
            int key = link->key;
            link = std::move(link->right);
            return key;
        }
        int key = takeMin(link->left);
        rebalance(link);
        return key;
    }

    static bool erase(std::unique_ptr<Node>& link, int key)
    {
        if (!link) return false;
        if (key < link->key)
        {
            if (!erase(link->left, key)) return false;
        }
        else if (key > link->key)
        {
            if (!erase(link->right, key)) return false;
        }
        else if (!link->left) { link = std::move(link->right); return true; }
        else if (!link->right) { link = std::move(link->left); return true; }
        else link->key = takeMin(link->right);
        rebalance(link);
        return true;
    }

    static void collect(const Node* n, std::vector<int>& out)
    {
        if (!n) return;
        collect(n->left.get(), out);
        out.push_back(n->key);
        collect(n->right.get(), out);
    }

    static bool check(const Node* n, long long lo, long long hi, int& h)
    {
        if (!n) { h = -1; return true; }
        if (n->key <= lo || n->key >= hi) return false;
        int hl, hr;
        if (!check(n->left.get(), lo, n->key, hl) || !check(n->right.get(), n->key, hi, hr)) return false;
        h = 1 + std::max(hl, hr);
        return n->height == h && hl - hr >= -1 && hl - hr <= 1;
    }

    std::unique_ptr<Node> root_;
    std::size_t size_ = 0;
};

unitTests:
#include <cmath>
#include <random>
#include <set>

TEST("small trees") {
    AvlSet s;
    CHECK_EQ(s.height(), -1);
    CHECK(s.isValid());
    for (int k : { 10, 20, 30 }) s.insert(k);         // right-right: one left rotation
    CHECK_EQ(s.height(), 1);
    CHECK(s.isValid());
    for (int k : { 25, 28 }) s.insert(k);             // a right-left case
    CHECK(s.isValid());
    CHECK_EQ(s.toVector(), (std::vector<int>{ 10, 20, 25, 28, 30 }));
    CHECK(!s.insert(25));
    CHECK_EQ(s.size(), std::size_t{ 5 });
    AvlSet t;
    for (int k : { 30, 10, 20 }) t.insert(k);         // left-right
    CHECK_EQ(t.height(), 1);
    CHECK(t.isValid());
}
TEST("100,000 sorted inserts stay balanced") {
    AvlSet s;
    for (int k = 0; k < 100000; ++k) s.insert(k);
    CHECK(s.isValid());
    CHECK(s.height() <= 1.44 * std::log2(100002.0));
    CHECK(s.contains(54321));
    CHECK(!s.contains(100000));
    for (int k = 0; k < 100000; k += 2) s.erase(k);
    CHECK(s.isValid());
    CHECK_EQ(s.size(), std::size_t{ 50000 });
    CHECK(s.height() <= 1.44 * std::log2(50002.0));
    CHECK(!s.contains(54320));
    CHECK(s.contains(54321));
}
TEST("erasing nodes with two children") {
    AvlSet s;
    for (int k = 1; k <= 31; ++k) s.insert(k);
    for (int k : { 16, 8, 24, 4, 12, 20, 28 }) { CHECK(s.erase(k)); CHECK(s.isValid()); }
    CHECK(!s.erase(16));
    CHECK_EQ(s.size(), std::size_t{ 24 });
}
TEST("matches std::set over 30,000 random operations") {
    AvlSet s;
    std::set<int> ref;
    std::mt19937 rng(2024);
    bool same = true;
    for (int step = 0; step < 30000; ++step)
    {
        int k = static_cast<int>(rng() % 2000);
        if (rng() % 2) same = same && s.insert(k) == ref.insert(k).second;
        else same = same && s.erase(k) == (ref.erase(k) == 1);
    }
    CHECK(same);
    CHECK(s.isValid());
    CHECK(s.toVector() == std::vector<int>(ref.begin(), ref.end()));
}

